    ? favorSupply
    : (favorSupply + lastEpochCirculatingSupply) / 2;

    lastEpochCirculatingSupply = favorSupply;

    uint256 _percentage = getFavorPrice() / 100;
    require(_percentage > 0, "Invalid favor price");

