        _percentage = max;
    } else if (_percentage < min) {
        _percentage = min;
    }

    uint256 _savedForGrove = (avgSupply * _percentage) / 1e18 / 24; // divide by 24 for each epoch per day

    if (_savedForGrove > 0) {
        _sendToGrove(_savedForGrove);
    }

}

