    uint80 poolId = cachePoolKey(address(pool), poolKey);

    _positions[tokenId] = Position({
        nonce: 0,
        operator: address(0),
        poolId: poolId,
        tickLower: params.tickLower,
        tickUpper: params.tickUpper,
        liquidity: liquidity,
        feeGrowthInside0LastX128: feeGrowthInside0LastX128,
        feeGrowthInside1LastX128: feeGrowthInside1LastX128,
        tokensOwed0: 0,
        tokensOwed1: 0
    });

    refundETH();

    emit IncreaseLiquidity(tokenId, liquidity, amount0, amount1);
}

function createPool(address tokenA, address tokenB, int24 tickSpacing, uint160 sqrtPriceX96)
    external
    override
    returns (address pool)
{
    require(tokenA != tokenB);
    (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    require(token0 != address(0));
    require(tickSpacingToFee[tickSpacing] != 0);
    require(getPool[token0][token1][tickSpacing] == address(0));
    if (legacyCLFactory.getPool({tokenA: token0, tokenB: token1, tickSpacing: tickSpacing}) != address(0)) {
        require(msg.sender == owner);
    }

    pool = Clones.cloneDeterministic({
        master: poolImplementation,
        salt: keccak256(abi.encode(token0, token1, tickSpacing))
    });
    CLPool(pool).initialize({
        _factory: address(this),
        _token0: token0,
        _token1: token1,
        _tickSpacing: tickSpacing,
        _factoryRegistry: address(factoryRegistry),
        _sqrtPriceX96: sqrtPriceX96
    });
    allPools.push(pool);
    _isPool[pool] = true;
    getPool[token0][token1][tickSpacing] = pool;
    // populate mapping in the reverse direction, deliberate choice to avoid the cost of comparing addresses
    getPool[token1][token0][tickSpacing] = pool;
    emit PoolCreated(token0, token1, tickSpacing, pool);
}

function outboundTransferCustomRefund(
    address _l1Token,
    address _refundTo,
    address _to,
    uint256 _amount,
    uint256 _maxGas,
    uint256 _gasPriceBid,
    bytes calldata _data
) public payable override returns (bytes memory res) {
    // fees are paid in native token, so there is no use for ether
    require(msg.value == 0, "NO_VALUE");

    // We don't allow bridging of native token to avoid having multiple representations of it 
    // on child chain. Native token can be bridged directly through inbox using depositERC20().
    require(_l1Token != _getNativeFeeToken(), "NOT_ALLOWED_TO_BRIDGE_FEE_TOKEN");

    return
        super.outboundTransferCustomRefund(
            _l1Token,
            _refundTo,
            _to,
            _amount,
            _maxGas,
            _gasPriceBid,
            _data
        );
}
